#include <stdio.h>

int main() {
    FILE *fp = fopen("input.txt", "r");
    int c, lines = 0, words = 0, chars = 0, inWord = 0;
    while ((c = fgetc(fp)) != EOF) {
        if (c == '\n') {
            lines++;
        }
        if (c == ' ' || c == '\n' || c == '\t') {
            inWord = 0;
        } else {
            chars++;
            if (!inWord) {
                words++;
                inWord = 1;
            }
        }
    }
    fclose(fp);
    printf("줄 %d 단어 %d 글자 %d\n", lines, words, chars);
    return 0;
}
